.version 7.8
.target sm_89
.address_size 64

.visible .entry conv3x3_bf16_nchw_no_bias(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 out_ptr,
    .param .u32 tot_elems
)
