    .reg .pred %p_exit, %p1, %p2, %p3;
    .reg .u32 %tidx, %bid, %bdim, %idx, %tot;
    .reg .u64 %in, %wt, %out, %addr, %addr_w, %addr_o;

    // index decode regs
    .reg .u32 %n, %oc, %oy, %ox, %r1, %r2;
    .reg .u32 %co_ohow, %ohow, %ow;
    .reg .u32 %tmp0, %tmp1, %tmp2, %tmp3, %tmp4, %tmp5, %tmp6;

    // loop counters
    .reg .u32 %ic, %ky, %kx;

    // accumulation regs
    .reg .f32 %acc, %vinf, %wf;

    .reg .b16 %in_b16, %w_b16, %out_b16;

    // Load params
    ld.param.u64 %in, [in_ptr];
    ld.param.u64 %wt, [wt_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %tot, [tot_elems];

