    setp.ge.u32 %p_exit, %idx, %tot;
    @%p_exit bra DONE;

    // constants
    // co_ohow = 32 * (222*222) = 1,577,088
    mov.u32 %co_ohow, 1577088;
    // ohow = 222*222 = 49,284
    mov.u32 %ohow, 49284;
    // ow = 222
    mov.u32 %ow, 222;

