    // tmp4 = oy + ky
    add.u32 %tmp4, %oy, %ky;
    // tmp5 = tmp3*224 + tmp4
    mul.lo.u32 %tmp5, %tmp3, 224;
    add.u32 %tmp5, %tmp5, %tmp4;
